using System.Collections.Generic;

namespace Cascade.Presentation
{
    public sealed partial class CascadeGame
    {
        static readonly Dictionary<string,string[]> collectionStories=new Dictionary<string,string[]>
        {
            {"leaf",new[]{"A lucky leaf.\nSmall enough for a pocket.\nStill catches on loose threads.","Листок на удачу.\nВ карман помещается легко.\nА за нитки всё равно цепляется.","Листочок на щастя.\nУ кишеню вміщається легко.\nА за нитки все одно чіпляється."}},
            {"sun",new[]{"A button with a sun on it.\nEasy to find in the bag,\neven before you've lit the lamp.","Пуговица с солнышком.\nВ сумке её легко нащупать,\nдаже пока фонарь не зажжён.","Ґудзик із сонечком.\nУ сумці його легко намацати,\nнавіть поки ліхтар не засвічений."}},
            {"sky",new[]{"A ribbon for the journey.\nNora checks the knot.\nThe wind gets at everything here.","Лента для дороги.\nНора проверяет узел.\nВетер тут что угодно унесёт.","Стрічка для дороги.\nНора перевіряє вузол.\nВітер тут що завгодно віднесе."}},
            {"moon",new[]{"A patch with a moon.\nAda says it belongs on a knee.\nRin has other plans.","Нашивка с луной.\nАда советует пришить на колено.\nУ Рин другие планы.","Нашивка з місяцем.\nАда радить пришити на коліно.\nУ Рін інші плани."}},
            {"wind_chime",new[]{"A chime for the doorway.\nYou hear someone arrive\nbefore they've had time to knock.","Колокольчик для двери.\nСразу слышно, что кто-то пришёл,\nещё прежде, чем постучит.","Дзвіночок для дверей.\nОдразу чути, що хтось прийшов,\nще перш ніж постукає."}},
            {"rain_badge",new[]{"A badge for wet weather.\nThe coat will need drying.\nThis just needs a wipe.","Значок для дождливой погоды.\nПлащ придётся сушить.\nА этот достаточно протереть.","Значок для дощової погоди.\nПлащ доведеться сушити.\nА цей досить протерти."}},
            {"copper_acorn",new[]{"A copper acorn.\nRose says it won't grow.\nAda wants one for her shelf.","Медный жёлудь.\nРоза ворчит: такой не посадишь.\nАда просит один для своей полки.","Мідний жолудь.\nРоза бурчить: такий не посадиш.\nАда просить один для своєї полиці."}},
            {"beacon_brooch",new[]{"A brooch shaped like a beacon.\nRin shows it to Ada first.\nShe checks the clasp, of course.","Брошь в виде маяка.\nРин первым делом показывает Аде.\nТа, конечно, проверяет застёжку.","Брошка у вигляді маяка.\nРін насамперед показує Аді.\nТа, звісно, перевіряє застібку."}},
            {"sky_pilot",new[]{"A pilot's cap.\nPull it down over your ears\nbefore the next gust comes.","Шапка для полётов.\nНатянуть поглубже на уши —\nи можно выходить на ветер.","Шапка для польотів.\nНатягнути глибше на вуха —\nі можна виходити на вітер."}},
            {"moth_mask",new[]{"An evening mask.\nNora recognises Rin's voice\nbefore she sees who's wearing it.","Маска для вечернего праздника.\nНора узнаёт Рин по голосу,\nдаже не успев разглядеть маску.","Маска для вечірнього свята.\nНора впізнає Рін за голосом,\nнавіть не встигнувши її роздивитись."}},
            {"garden_festival",new[]{"An outfit for the garden party.\nRose let Rin pick flowers.\nJust not from the seedling beds.","Наряд для праздника в саду.\nРоза разрешила брать цветы.\nТолько не из рассадника.","Вбрання для свята в саду.\nРоза дозволила брати квіти.\nТільки не з розсадника."}},
            {"cloud_gardener",new[]{"Clothes for a day in the garden.\nNo need to mind your knees\nwhen you stop to plant something.","Одежда для работы в саду.\nМожно встать на колени у грядки\nи не жалеть праздничный наряд.","Одяг для роботи в саду.\nМожна стати на коліна біля грядки\nй не шкодувати святкового вбрання."}},
            {"explorer_hat",new[]{"A hat for a long walk.\nThere's a map in the bag\nand a pencil behind one ear.","Шляпа для долгой дороги.\nКарта в сумке,\nкарандаш за ухом.","Капелюх для довгої дороги.\nКарта в сумці,\nолівець за вухом."}},
            {"frog_suit",new[]{"A hood for the rain.\nRin can watch the puddles\nwithout rain running into both ears.","Капюшон на случай дождя.\nМожно разглядывать лужи,\nне заливая водой оба уха.","Каптур на випадок дощу.\nМожна роздивлятися калюжі,\nне заливаючи водою обидва вуха."}},
            {"star_knight",new[]{"A knight's cape.\nAda insists on a loose knot.\nA cape should come off if it catches.","Рыцарский плащ.\nАда велела завязать не туго:\nзацепится — должен отвязаться.","Лицарський плащ.\nАда звеліла зав'язати не туго:\nзачепиться — має розв'язатись."}},
            {"fox_mask",new[]{"A fox mask.\nThe ears fit over Rin's ears.\nAda still asks where the mouse went.","Лисья маска.\nУши надеваются поверх своих.\nАда всё спрашивает, куда делась мышь.","Лисяча маска.\nВуха надягаються поверх своїх.\nАда все питає, куди поділася миша."}},
            {"mushroom_cap",new[]{"A mushroom cap.\nRose had to look twice\nbefore she recognised Rin.","Шляпа-гриб.\nРозе пришлось присмотреться,\nпрежде чем она узнала Рин.","Капелюх-гриб.\nРозі довелося придивитися,\nперш ніж вона впізнала Рін."}},
            {"bee_suit",new[]{"Stripes and wings.\nThe flowers are much too big\nto carry home in this outfit.","Полоски и крылышки.\nТолько цветы всё равно большие:\nна спине домой не унести.","Смужки й крильця.\nТа квіти все одно завеликі:\nна спині додому не донести."}},
            {"winter_hood",new[]{"A hood for the pass.\nSnow settles on the outside.\nThe ears underneath stay warm.","Капюшон для перевала.\nСнаружи на нём лежит снег.\nА ушам внутри тепло.","Каптур для перевалу.\nЗовні на ньому лежить сніг.\nА вухам усередині тепло."}},
            {"pirate_hat",new[]{"A hat for a captain.\nClara asks Rin about the boat.\nThe hat was easier to find.","Шляпа для капитана.\nКлара спрашивает, где лодка.\nСо шляпой пока проще.","Капелюх для капітана.\nКлара питає, де човен.\nЗ капелюхом поки простіше."}},
            {"jester_suit",new[]{"Bells on the outfit.\nRin tries to sneak past Ada.\nThe bells give the game away.","Наряд с бубенчиками.\nРин пытается подкрасться к Аде.\nБубенчики выдают заранее.","Вбрання з бубонцями.\nРін намагається підкрастися до Ади.\nБубонці завчасно видають."}},
            {"constellation_mage",new[]{"A cloak with constellations.\nFelix checks the stars on it.\nRin just wants to wear it.","Плащ с созвездиями.\nФеликс проверяет рисунок звёзд.\nА Рин просто хочет его носить.","Плащ із сузір'ями.\nФелікс перевіряє малюнок зірок.\nА Рін просто хоче його носити."}},
            {"paper_crane",new[]{"A paper crane.\nOne wing crumpled in the bag.\nRin carefully straightens it.","Бумажный журавлик.\nВ сумке помялось одно крыло.\nРин бережно его расправляет.","Паперовий журавлик.\nУ сумці зім'ялося одне крило.\nРін дбайливо його розправляє."}},
            {"tiny_comet",new[]{"A comet with a long tail.\nRin turns it over in one paw.\nEven the back is worth a look.","Комета с длинным хвостом.\nРин вертит её в лапе.\nДаже с обратной стороны интересно.","Комета з довгим хвостом.\nРін крутить її в лапі.\nНавіть зі звороту цікаво."}},
            {"dew_bell",new[]{"A bell with a drop of dew.\nIt rings, and Rin looks up.\nPerhaps someone needs the rope.","Колокольчик с каплей росы.\nЗвенит — и Рин смотрит вверх:\nможет, кого-то надо подстраховать.","Дзвіночок із краплею роси.\nДзвенить — і Рін дивиться вгору:\nможе, когось треба підстрахувати."}},
            {"night_flower",new[]{"A flower for evening walks.\nHard to notice in daylight.\nMuch easier to spot at dusk.","Цветок для вечерних вылазок.\nДнём его почти не замечаешь.\nВ сумерках сразу видно.","Квітка для вечірніх вилазок.\nУдень її майже не помічаєш.\nУ сутінках одразу видно."}},
            {"cloud_kite",new[]{"A kite for a windy day.\nIt takes a while to untie the tail.\nThen up it goes.","Воздушный змей.\nРин долго распутывает хвост.\nЗато как он тянется вверх!","Повітряний змій.\nРін довго розплутує хвіст.\nЗате як він тягнеться вгору!"}},
            {"fern_compass",new[]{"A compass with a fern leaf.\nOscar's map is in the bag too.\nRin will need them both.","Компас с листом папоротника.\nКарта Оскара тоже в сумке.\nПонадобятся оба.","Компас із листком папороті.\nКарта Оскара теж у сумці.\nУ дорозі потрібні обидві речі."}},
            {"amber_wing",new[]{"An amber moth.\nHold it up to the lamp\nto see the veins in its wings.","Янтарный мотылёк.\nПоднесёшь к фонарю —\nвидны жилки на крыльях.","Бурштиновий метелик.\nПіднесеш до ліхтаря —\nвидно прожилки на крилах."}},
            {"moon_boat",new[]{"A boat that fits in one paw.\nClara would check the bottom.\nEven on a boat this small.","Лодочка размером с ладонь.\nКлара проверила бы дно.\nДаже у такой.","Човник розміром із долоню.\nКлара перевірила б дно.\nНавіть у такого."}},
            {"petal_drift",new[]{"Petals above the islands.\nThey gather beside the frame,\nthen a gust carries them on.","Лепестки над островами.\nСоберутся у края —\nи порыв унесёт их дальше.","Пелюстки над островами.\nЗберуться біля краю —\nі порив понесе їх далі."}},
            {"firefly_dance",new[]{"Fireflies in the sky.\nEasier to see in the evening.\nIn daylight they look like sparks.","Светлячки в небе.\nВечером их лучше видно.\nА днём легко принять за искры.","Світлячки в небі.\nУвечері їх краще видно.\nА вдень легко сплутати з іскрами."}},
            {"butterfly_garden",new[]{"Butterflies and pollen.\nFor a moment it feels\nlike a window opened on a garden.","Бабочки и пыльца.\nНа минуту кажется,\nчто открыли окно в сад.","Метелики й пилок.\nНа хвилину здається,\nщо відчинили вікно в сад."}},
            {"swallow_flock",new[]{"Swallows above the islands.\nBarely a sound from this far away.\nPlenty to watch.","Ласточки над островами.\nИздалека их почти не слышно.\nА за полётом можно следить долго.","Ластівки над островами.\nЗдалеку їх майже не чути.\nА за польотом можна стежити довго."}},
            {"dragonfly_stream",new[]{"Dragonflies over the islands.\nA pause in mid-air, then off again.\nThere's plenty to inspect.","Стрекозы над островами.\nЗависнут в воздухе — и дальше.\nВсё им нужно осмотреть.","Бабки над островами.\nЗависнуть у повітрі — і далі.\nУсе їм треба оглянути."}},
            {"lantern_flight",new[]{"Lanterns drift across the sky.\nRin watches them go\nuntil they're only dots.","Фонарики плывут по небу.\nРин провожает их взглядом,\nпока не станут точками.","Ліхтарики пливуть небом.\nРін проводжає їх поглядом,\nпоки не стануть цятками."}},
            {"snow_wings",new[]{"Snow and winter birds.\nAgainst the dark sky\nyou can see every wingbeat.","Снег и зимние птицы.\nНа тёмном небе видно\nкаждое движение крыла.","Сніг і зимові птахи.\nНа темному небі видно\nкожен рух крила."}},
            {"comet_trails",new[]{"Comets leave trails in the sky.\nBetween them,\nnight moths circle.","Кометы оставляют следы.\nМежду ними кружатся\nночные мотыльки.","Комети залишають сліди.\nМіж ними кружляють\nнічні метелики."}},
            {"ribbon_kites",new[]{"Kites with ribbon tails.\nThe tails nearly tangle.\nGood thing there's room up here.","Воздушные змеи с лентами.\nЛенты всё норовят запутаться.\nХорошо, что здесь много места.","Повітряні змії зі стрічками.\nСтрічки все норовлять сплутатись.\nДобре, що тут багато місця."}},
            {"origami_cranes",new[]{"Cranes folded from paper.\nEach wing bends a little differently.\nThey still fly as one flock.","Журавлики из бумаги.\nУ каждого свой сгиб крыла.\nВместе держатся одной стаей.","Журавлики з паперу.\nУ кожного свій згин крила.\nРазом тримаються однією зграєю."}},
            {"bubble_dream",new[]{"Bubbles rise over the islands.\nPink when they turn one way,\nblue when they turn the other.","Пузыри над островами.\nПовернутся — станут розовыми,\nещё поворот — голубыми.","Бульбашки над островами.\nПовернуться — стануть рожевими,\nще поворот — блакитними."}},
            {"aurora_veil",new[]{"Bands of northern light.\nLumi grew up with this sight.\nRin still stops to look up.","Полосы северного сияния.\nЛюми знакомы с детства.\nА Рин всё смотрит вверх.","Смуги північного сяйва.\nЛюмі знайомі з дитинства.\nА Рін усе дивиться вгору."}},
            {"garden_frame",new[]{"A frame of leaves.\nLike a window the ivy\nhas nearly covered over summer.","Рамка с листьями.\nКак окно, которое за лето\nпочти заросло плющом.","Рамка з листям.\nНаче вікно, яке за літо\nмайже заросло плющем."}},
            {"sky_frame",new[]{"Feathers around the picture.\nThey look light enough\nfor a breath to lift them.","Перья по краям картины.\nНа вид такие лёгкие —\nкажется, можно сдуть.","Пір'я по краях картини.\nНа вигляд таке легке —\nздається, можна здмухнути."}},
            {"copper_frame",new[]{"A copper frame.\nThe sort you'd hang in a workshop\nbeside the drawings.","Медная рамка.\nТакие вешают в мастерской,\nрядом с чертежами.","Мідна рамка.\nТакі вішають у майстерні,\nпоруч із кресленнями."}},
            {"lunar_frame",new[]{"A frame with a moon.\nLike the observatory window\nafter the evening rounds.","Рамка с луной.\nПохожа на окно обсерватории\nпосле вечернего обхода.","Рамка з місяцем.\nСхожа на вікно обсерваторії\nпісля вечірнього обходу."}},
        };
        UiCopy ReferenceTrophyDescription(string id)
        {
            return collectionStories.TryGetValue(id,out var words)?ReferenceCopy(words[0],words[1],words[2]):TrophyBenefit(id);
        }
    }
}
